Tests.EqualCheck("match pattern anchored at start of line", true, matchPattern("apple pie", "^apple"))
Tests.EqualCheck("do not match when pattern appears later in line", false, matchPattern("pie apple", "^apple"))
Tests.EqualCheck("match single character anchored at start", true, matchPattern("log: error", "^l"))
Tests.EqualCheck("do not match single character if not at start", false, matchPattern("blog: error", "^l"))
Tests.EqualCheck("match character class anchored at start", true, matchPattern("3 apples", `^\d \w\w\w\w\w\w`))
Tests.EqualCheck("do not match character class if not at start", false, matchPattern("buy 3 apples", `^\d \w\w\w\w\w\w`))
Tests.EqualCheck("match positive character group anchored at start", true, matchPattern("cat", `^[abc]at`))
Tests.EqualCheck("do not match positive character group anchored if not at start", false, matchPattern("a cat", `^[abc]at`))
Tests.EqualCheck("match negative character group anchored at start", true, matchPattern("dog", `^[^abc]og`))
Tests.EqualCheck("do not match negative group if excluded character is at start", false, matchPattern("bog", `^[^abc]og`))
Tests.EqualCheck("unanchored pattern still matches anywhere", true, matchPattern("fresh apples", "apples"))
Tests.EqualCheck("unanchored pattern matches in middle of line", true, matchPattern("the 3 dogs barked", `\d \w\w\w\w`))
Tests.EqualCheck("empty pattern matches any line", true, matchPattern("hello", ""))
Tests.EqualCheck("lone caret matches any line at start", true, matchPattern("hello", "^"))
Tests.EqualCheck("lone caret matches empty line", true, matchPattern("", "^"))
Tests.EqualCheck("anchored pattern does not match empty line when pattern non-empty", false, matchPattern("", "^a"))
